<template>
    <div class="vertical-gallery" ref="vertical">
        <div ref="action"
             @click="prevFun" class="g-category-nav g-category-up"><span class="material-icons">arrow_drop_up</span>
        </div>
        <div class="vertical-content"
             >
            <div class="vertical-container"
                 ref="verticalContainer"
                 :style="{'top': `${contentTop}px`}">
                <slot></slot>        
            </div>
        </div>
         
        <!-- :style="{'height': `${height - actionHeight}px`, 'top': `${actionHeight/2}px`}" -->
    </div>
    <div @click="nextFun" class="g-category-nav g-category-down"><span class="material-icons">arrow_drop_down</span></div>
</template>

<script>
export default {
    data() {
        return {
            contentTop: 0,
            prevShow: false,
            nextShow: true,
            nextEnd: false,
            height: 375, // 根據您的 CSS，這應該是 375px
            actionHeight: 0, // 您需要在 mounted 鉤子中設置這個值
            contentHeight: 0, // 這個值應該在 mounted 鉤子中計算
        };
    },
    props:{
       itemHeight: {
            type: Number,
            // default: 100
        },
        length: {
            type: Number,
        }
    },
    mounted() {
        this.actionHeight = this.$refs.action.clientHeight;
        this.contentHeight = this.length * this.itemHeight;
    },
    methods: {
        nextFun() {
            let totalHeight = this.length * this.itemHeight;
            let visibleHeight = this.height - this.actionHeight * 2 - 24; // 可見區域高度
            let maxScroll = totalHeight - visibleHeight; // 最大可滾動距離
            let remainingScroll = maxScroll + this.contentTop; // 剩餘可滾動距離

            if (remainingScroll > 0) {
                if (remainingScroll > this.itemHeight) {
                    // 如果剩餘可滾動距離大於一個項目高度，則滾動一個項目高度
                    this.contentTop -= this.itemHeight;
                } else {
                    // 否則滾動剩餘距離
                    this.contentTop -= remainingScroll;
                }
                this.prevShow = true;
            }

            // 檢查是否已經滾動到底部
            if (this.contentTop <= -maxScroll) {
                this.nextShow = false;
                this.nextEnd = true;
            }
        },
        prevFun() {
            if (this.contentTop < 0 && this.contentTop + this.itemHeight < 0) {
                this.contentTop += this.itemHeight;
                this.nextShow = true;
            }
            else {
                this.contentTop = 0;
                this.prevShow = false;
                this.nextEnd = true;
            }
        }
    }
};
</script>

<style lang='less'>
    .vertical-gallery {
        position: relative;
        height: 100%;
        // overflow: hidden;

        .vertical-content {
            position: absolute;
            min-height: 350px;
            height: 100%;
            top: 0;
            left: 0;
            width: 100%;
            // overflow: hidden;
            background-color: #fff;
        }
        .vertical-container {
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
            transition: all .3s linear;
        }
    }
</style>